import os
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190125", "20190126", "20190127", "20190128", "20190129"]

targets = [
    ("陕京二线", "石家庄站", "永清站"),
    ("冀宁线", "南京站", "南通站"),
]

sums = {t: 0.0 for t in targets}
