import csv
import os
from pathlib import Path

# The three daily node files to process
files = ['20191106_node.csv', '20191107_node.csv', '20191118_node.csv']

# Target stations
targets = ['靖边站', '南通站']

# Initialize accumulators (absolute flow sums per station across all files and pipelines)
abs_flows = {t: 0.0 for t in targets}

# Also track per-file breakdown
per_file = {t: {} for t in targets}

for fname in files:
    # Each file exists once in the NODE_FLOW_DIR env dir
    node_dir = Path(os.environ['NODE_FLOW_DIR'])
    csv_path = node_dir / fname
    with open(csv_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        file_flows = {t: 0.0 for t in targets}
        for row in reader:
            station = row['站名'].strip()
            if station in targets:
                # "计算流量" (computed flow) column holds the signed flow value
                calc_flow_str = row.get('计算流量', '').strip()
                if calc_flow_str:
                    try:
                        flow_val = float(calc_flow_str)
                        abs_val = abs(flow_val)
                        abs_flows[station] += abs_val
                        file_flows[station] += abs_val
                    except ValueError:
                        print(f"Warning: could not parse flow for {station} in {fname}: '{calc_flow_str}'")
        for t in targets:
            per_file[t][fname] = file_flows[t]

# Print results
print("=== Per-file absolute flows (across all pipelines) ===")
for t in targets:
    for fname in files:
        print(f"  {t} - {fname}: {per_file[t][fname]:.3f}")

print("\n=== Cumulative absolute node flows (window 2019-11-06 to 2019-11-18) ===")
for t in targets:
    print(f"  {t}: {abs_flows[t]:.3f}")

print("\n=== Comparison ===")
jingbian = abs_flows['靖边站']
nantong = abs_flows['南通站']
if jingbian > nantong:
    print(f"  靖边站 吞吐更高: {jingbian:.3f} > {nantong:.3f} (差值 {jingbian - nantong:.3f})")
elif nantong > jingbian:
    print(f"  南通站 吞吐更高: {nantong:.3f} > {jingbian:.3f} (差值 {nantong - jingbian:.3f})")
else:
    print(f"  两站吞吐相等: {jingbian:.3f}")

